import sys, itertools, random, json
sys.path.insert(0,'/workspace/submission')
from netnomos.finite import compile_job

def eval_ref(r,row,names): return row[r[0]][names[r[1]]]

def eval_term(t,row,names):
    if 'const' in t:return t['const']
    if 'sum' in t:return sum(eval_ref(r,row,names) for r in t['sum'])
    if 'scale' in t:return t['scale']*eval_ref(t['ref'],row,names)
    return eval_ref(t['ref'],row,names)

def cmp(a,op,b):
    return {'eq':a==b,'ne':a!=b,'lt':a<b,'le':a<=b,'gt':a>b,'ge':a>=b}[op]

def eval_pred(p,row,names):
    if p['kind']=='cmp':return cmp(eval_term(p['left'],row,names),p['op'],eval_term(p['right'],row,names))
    vals=[row[s][names[p['field']]] for s in range(len(row))]
    if p['kind']=='any':return any(cmp(v,p['op'],p['value']) for v in vals)
    return all(cmp(v,p['op'],p['value']) for v in vals)

def gen_job(rng):
    nf=rng.randint(1,3); K=rng.randint(1,3)
    fields=[]
    for j in range(nf):
        typ=rng.choice(['id','flag','size','count','time'])
        if typ in ('id','flag'):
            dom=sorted(rng.sample(range(0,6),rng.randint(1,4)))
        else:
            dom=sorted(rng.sample(range(0,12),rng.randint(1,5)))
        fields.append({'name':f'f{j}','type':typ,'domain':dom})
    # cap universe
    univ=1
    for _ in range(K):
      for f in fields:univ*=len(f['domain'])
    if univ>1500:return None
    preds=[]
    numeric=[f for f in fields if f['type'] in ('size','count','time')]
    n=p=0
    P=rng.randint(0,7)
    for pi in range(P):
        kind=rng.choice(['cmp','cmp','any','all'])
        if kind in ('any','all'):
            f=rng.choice(fields)
            if f['type'] in ('id','flag'):ops=['eq','ne']
            else:ops=['eq','ne','lt','le','gt','ge']
            preds.append({'kind':kind,'field':f['name'],'op':rng.choice(ops),'value':rng.randint(0,12)})
        else:
            # choose compatible type, build terms
            typ=rng.choice(['id','flag','size','count','time'])
            tf=[f for f in fields if f['type']==typ]
            if not tf:continue
            def term():
                choices=['ref','const']
                if typ in ('size','count','time'):choices += ['sum','scale']
                c=rng.choice(choices)
                if c=='ref':
                    f=rng.choice(tf); return {'ref':[rng.randrange(K),f['name']]}
                if c=='const':return {'const':rng.randint(0,20),'type':typ}
                if c=='scale':
                    f=rng.choice(tf); return {'scale':rng.randint(0,4),'ref':[rng.randrange(K),f['name']]}
                # sum distinct refs all same type, 1..min(K,len(tf)*?) distinct max K
                allrefs=[(s,f['name']) for s in range(K) for f in tf]
                maxn=min(K,len(allrefs))
                refs=rng.sample(allrefs,rng.randint(1,maxn))
                return {'sum':[list(r) for r in refs]}
            a=term();b=term()
            if typ in ('id','flag'):ops=['eq','ne']
            else:ops=['eq','ne','lt','le','gt','ge']
            preds.append({'kind':'cmp','left':a,'op':rng.choice(ops),'right':b})
    # generate all worlds and random train incl collisions
    domains=[f['domain'] for f in fields]
    flat_domains=[f['domain'] for _s in range(K) for f in fields]
    worlds=[]
    for flat in itertools.product(*flat_domains):
        worlds.append([list(flat[s*nf:(s+1)*nf]) for s in range(K)])
    # Actually domains is list of K lists, each list of nf-lists; product chooses one row-list per slot
    train=[rng.choice(worlds) for _ in range(rng.randint(1,20))]
    width=rng.randint(1,4)
    job={'fields':fields,'slots':K,'predicates':preds,'width':width,'train':train,'approved':[],'queries':[]}
    res=compile_job(job)
    # oracle rules
    W=len(worlds)
    names={f['name']:i for i,f in enumerate(fields)}
    truths=[[eval_pred(p,w,names) for p in preds] for w in worlds]
    T=[[[eval_pred(p,w,names) for p in preds] for w in train[i]] for i in range(len(train))]
    expected=[]
    for L in range(1,min(width,len(preds))+1):
      for C in itertools.combinations(range(len(preds)),L):
        if not all(any(T[i][p] for p in C) for i in range(len(train))):continue
        ws=[]
        ok=True
        for p in C:
            found=None
            for i in range(len(train)):
                if T[i][p] and not any(T[i][q] for q in C if q!=p):
                    found=i;break
            if found is None:ok=False;break
            ws.append(found)
        if not ok:continue
        cex=None
        for i,tr in enumerate(truths):
            if not any(tr[p] for p in C):cex=i;break
        if cex is None:continue
        expected.append({'clause':list(C),'witnesses':ws,'counterexample':cex})
    if expected!=res['rules']:
        print('MISMATCH RULES')
        print(json.dumps(job,indent=1))
        print('expected',expected)
        print('actual',res['rules'])
        return False
    # approval random subset of expected plus some fake
    exp_t=[tuple(r['clause']) for r in expected]
    appr=[]
    for c in exp_t:
        if rng.random()<.5: appr.append(list(c))
    # add fake combos that didn't appear (some)
    for _ in range(rng.randint(0,2)):
        if preds:
          fake=tuple(sorted(rng.sample(range(len(preds)),rng.randint(1,min(width,len(preds))))))
